/**
 * GlucoCare - curated education library (Phase 10)
 * -------------------------------------------------------------
 * FIXED, reviewed educational content. Nothing here is generated by AI and
 * nothing is changed per user - personalisation only changes the ORDER in
 * which these items are shown (lib/personalize.ts).
 *
 * Content rules: general and educational; no diagnosis; no medicines or
 * doses; no promised outcomes; always points to a qualified professional.
 * Reference numbers are the SAME ones the assessment engine uses
 * (src/data/referenceRanges.ts) with the same citations [R1]-[R3].
 */

export type EducationTag =
  | "glucose"
  | "hba1c"
  | "bmi"
  | "blood-pressure"
  | "nutrition"
  | "activity"
  | "smoking"
  | "monitoring"
  | "clinician"
  | "symptoms"
  | "family-history"
  | "safety"
  | "general";

export interface EducationItem {
  id: string;
  title: string;
  summary: string;
  tags: EducationTag[];
  /** In-app link to read more. */
  href: string;
  linkLabel: string;
  citation?: string;
  /** Order among equally relevant items (higher first). */
  basePriority: number;
}

